//! Protocol Buffers targets: the pinned protoc compiles every `.proto` under the proto root
//! into a FileDescriptorSet, and prost-build turns that into message types, one
//! `<package>.rs` per package. No service generator is configured, so `service`
//! definitions produce no code (bindings are generated by the layers that use a contract).
//!
//! Determinism: the sources are copied with LF line endings into a temporary directory and
//! compiled from there by relative `/` paths, so neither line endings nor the checkout path
//! reach protoc's output; prost-build formats with prettyplease.

use std::collections::BTreeMap;
use std::fs;
use std::path::Path;
use std::process::Command;

use prost::Message;
use prost_types::FileDescriptorSet;

use crate::config::Proto;
use crate::output::{self, GeneratedDir, lf};
use crate::protoc::Protoc;
use crate::{Error, ErrorKind};

#[derive(Debug, Clone, Default)]
pub struct ProtoSettings {
    /// prost-build `Config::bytes` paths.
    pub bytes: Vec<String>,
    /// prost-build `Config::btree_map` paths.
    pub btree_map: Vec<String>,
}

fn io(path: &Path, e: std::io::Error) -> Error {
    Error::new(ErrorKind::Io, format!("{}: {e}", path.display()))
}

/// Every `.proto` file below `root`, as sorted `/`-separated relative paths. Symlinks are
/// not followed. A root without any `.proto` is an error.
pub fn discover(root: &Path) -> Result<Vec<String>, Error> {
    fn walk(dir: &Path, rel: &str, out: &mut Vec<String>) -> Result<(), Error> {
        for e in fs::read_dir(dir).map_err(|e| io(dir, e))? {
            let e = e.map_err(|e| io(dir, e))?;
            let name = e.file_name().to_string_lossy().into_owned();
            let child = if rel.is_empty() {
                name.clone()
            } else {
                format!("{rel}/{name}")
            };
            let meta = fs::symlink_metadata(e.path()).map_err(|err| io(&e.path(), err))?;
            if meta.is_dir() {
                walk(&e.path(), &child, out)?;
            } else if meta.is_file() && name.ends_with(".proto") {
                out.push(child);
            }
        }
        Ok(())
    }
    let mut out = Vec::new();
    walk(root, "", &mut out)?;
    out.sort();
    if out.is_empty() {
        return Err(Error::new(
            ErrorKind::Definition,
            format!("{}: no .proto files", root.display()),
        ));
    }
    Ok(out)
}

/// prost-build over a FileDescriptorSet: file name (`<package>.rs`) → body, LF-only.
pub fn generate_fds(
    fds: FileDescriptorSet,
    s: &ProtoSettings,
) -> Result<BTreeMap<String, String>, Error> {
    let gen_err = |m: String| Error::new(ErrorKind::Generate, format!("prost-build: {m}"));
    let out = tempfile::tempdir().map_err(|e| gen_err(e.to_string()))?;
    let mut c = prost_build::Config::new();
    c.out_dir(out.path());
    if !s.bytes.is_empty() {
        c.bytes(&s.bytes);
    }
    if !s.btree_map.is_empty() {
        c.btree_map(&s.btree_map);
    }
    c.compile_fds(fds).map_err(|e| gen_err(e.to_string()))?;
    let mut files = BTreeMap::new();
    for e in fs::read_dir(out.path()).map_err(|e| io(out.path(), e))? {
        let e = e.map_err(|e| io(out.path(), e))?;
        let name = e.file_name().to_string_lossy().into_owned();
        if name == "_.rs" {
            return Err(gen_err(
                "a .proto file without a `package` (output `_.rs`) is not supported".into(),
            ));
        }
        let text = fs::read_to_string(e.path()).map_err(|err| io(&e.path(), err))?;
        files.insert(name, lf(&text));
    }
    Ok(files)
}

/// Generates one `[[proto]]` target with the verified `protoc`.
pub fn generate(root: &Path, p: &Proto, protoc: &Protoc) -> Result<GeneratedDir, Error> {
    let src = root.join(&p.root);
    let files = discover(&src)?;
    let work = tempfile::tempdir().map_err(|e| Error::new(ErrorKind::Io, e.to_string()))?;
    let tree = work.path().join("src");
    for f in &files {
        let from = src.join(f);
        let text = fs::read_to_string(&from).map_err(|e| io(&from, e))?;
        let to = tree.join(f);
        fs::create_dir_all(to.parent().expect("relative path has a parent"))
            .map_err(|e| io(&to, e))?;
        fs::write(&to, lf(&text)).map_err(|e| io(&to, e))?;
    }
    let fds_path = work.path().join("descriptor_set.pb");
    let out = Command::new(protoc.path())
        .current_dir(&tree)
        .arg("--proto_path=.")
        .arg("--include_imports")
        .arg("--include_source_info")
        .arg(format!("--descriptor_set_out={}", fds_path.display()))
        .args(&files)
        .output()
        .map_err(|e| Error::new(ErrorKind::Protoc, format!("cannot run protoc: {e}")))?;
    if !out.status.success() {
        // protoc reports paths relative to the proto root; name the root for the reader.
        return Err(Error::new(
            ErrorKind::Definition,
            format!(
                "protoc failed on {} ({}):\n{}",
                p.root,
                out.status,
                String::from_utf8_lossy(&out.stderr).trim_end()
            ),
        ));
    }
    let bytes = fs::read(&fds_path).map_err(|e| io(&fds_path, e))?;
    let fds = FileDescriptorSet::decode(bytes.as_slice()).map_err(|e| {
        Error::new(
            ErrorKind::Protoc,
            format!("protoc wrote an unreadable descriptor set: {e}"),
        )
    })?;
    let settings = ProtoSettings {
        bytes: p.bytes.clone(),
        btree_map: p.btree_map.clone(),
    };
    let source = format!("{} (protoc {})", p.root, protoc.version());
    let files = generate_fds(fds, &settings)?
        .into_iter()
        .map(|(name, body)| {
            let text = output::file(&source, &body);
            (name, text)
        })
        .collect();
    Ok(GeneratedDir {
        dir: p.out.clone(),
        files,
    })
}
